local function clampGui(gui)
	local function clampPosition()
		local vpSize = workspace.CurrentCamera.ViewportSize
		local guiSize = gui.AbsoluteSize
		local pos = gui.Position

		local rawX = pos.X.Scale * vpSize.X + pos.X.Offset
		local rawY = pos.Y.Scale * vpSize.Y + pos.Y.Offset

		local clampedX = math.clamp(rawX, 0, math.max(0, vpSize.X - guiSize.X))
		local clampedY = math.max(rawY, 0)

		gui.Position = UDim2.new(0, clampedX, 0, clampedY)
	end

	clampPosition()
	gui:GetPropertyChangedSignal("Position"):Connect(clampPosition)
	workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(clampPosition)
end

local function setupShadow(frame, shadowLabel)
	local function updateShadow()
		local framePos = frame.Position
		shadowLabel.Position = UDim2.new(
			framePos.X.Scale, framePos.X.Offset - 10,
			framePos.Y.Scale, framePos.Y.Offset - 14
		)
	end
	updateShadow()
	frame:GetPropertyChangedSignal("Position"):Connect(updateShadow)
end

